def pick(fields, candidates):
    low = {f.lower().strip(): f for f in fields}
    for c in candidates:
        if c in low:
            return low[c]
    # fallback substring match
    for c in candidates:
        for lf, orig in low.items():
            if c in lf:
                return orig
    return None

id_f = pick(fields, ['id', 'user_id', 'userid', 'user'])
name_f = pick(fields, ['name', 'user', 'username'])
country_f = pick(fields, ['country', 'nation'])
